package p;
 class Registry #(type T = int);
  static int count;
  static function T create(); T object = new; count++; return object; endfunction
 endclass
 class Obj; typedef Registry #(Obj) type_id; endclass
 class Impl #(type T = int); typedef Registry #(Impl #(T)) type_id; endclass
endpackage
module Top;
 import p::*;
 initial begin
  automatic Obj o = Obj::type_id::create();
  automatic Impl #(byte) b = Impl #(byte)::type_id::create();
  $display("[%0d %0d %0d %0d]", Obj::type_id::count, p::Obj::type_id::count, Impl #(byte)::type_id::count, Registry #(Obj)::count);
 end
endmodule
